pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        // Admissible domain: actor must be a plain EOA (else transfer to it could
        // fail for reasons unrelated to the bug); timestamp is any value.
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.warp(ts);

        uint bankBefore = address(this).balance;
        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // A win is exactly the successful play in which the bank received the FEE.
            if (address(this).balance == bankBefore + 1) {
                // General rule: after a winning play the pot is fully drained.
                assertTrue(c.pot() == 0);
            } else {
                assertTrue(true);
            }
        } else {
            assertTrue(true);
        }
    }
}

