pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.warp(timestamp);
        vm.roll(timestamp);
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();
        // General rule: the pot accounting always matches the real balance.
        // P: after non-win pot == 10 == balance; after win pot == 0 == balance.
        // M: after a win pot == 1 while balance == 0 -> violated.
        assertTrue(c.pot() == address(c).balance);
    }
}

