import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warp, address actor) public {
        vm.assume(actor != address(0));
        vm.warp(warp);
        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() { ok = true; } catch { ok = false; }
        if (!ok) {
            // reverting calls are outside the admissible domain; the invariant
            // is asserted only over completed plays
            return;
        }
        assertEq(c.pot() % 10, 0);
    }
}

