import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 diff, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.warp(ts);
        vm.roll(diff);

        uint256 random = uint256(keccak256(abi.encodePacked(ts, diff))) % 2;
        vm.assume(random == 0); // admissible domain: plays that WIN (fully reachable by fuzzer via ts/diff)

        uint256 ticket = 10;
        vm.deal(actor, ticket);
        vm.prank(actor);
        c.play{value: ticket}();

        // Rule: a winning play pays out fee + pot, so the contract must end with zero balance.
        assertTrue(address(c).balance == 0);
    }
}

