pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 ts, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(ts > 0);

        // The randomness the contract will compute is fully determined by the
        // (timestamp, difficulty) pair; only the timestamp is fuzzed here.
        uint256 difficulty = block.difficulty;
        vm.warp(ts);

        uint256 random = uint(keccak256(abi.encodePacked(ts, difficulty))) % 2;

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // General rule: whenever the random draw is 1, no payout occurs and the
        // pot keeps the just-deposited ticket amount (10). The reference always
        // obeys this; the '% 1' mutant always pays out, leaving pot == 0, so it
        // violates the rule for any input with random == 1.
        assertTrue(
            (random == 1) ? (c.pot() == 10) : true,
            "pot must hold the ticket when the random draw is 1"
        );
    }
}

