pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 ts, uint64 diff, address actor) public {
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c) && actor != address(this));
        vm.warp(ts);
        vm.roll(diff);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        // Rule: when the lottery random == 1, no payout occurred and the pot keeps the ticket.
        assertTrue(random == 0 || c.pot() == 10);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function invMutTest(uint amt) public {
        require(address(this).balance >= 2 * amt);

        (bool ok1, ) = address(c).call{value: amt}(abi.encodeWithSelector(c.play.selector));
        require(ok1);

        (bool ok2, ) = address(c).call{value: amt}(abi.encodeWithSelector(c.play.selector));

        assert(ok2);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public {
        require(amount == C.TICKET_AMOUNT);
        require(address(this).balance >= 2 * amount);

        uint start = address(this).balance;

        c.play{value: amount}();
        c.play{value: amount}();

        uint received = address(this).balance + 2 * amount - start;

        assert(c.pot() == 2 * amount || received > 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint a) public {
        require(address(this).balance >= a);
        uint balBefore = address(c).balance;
        bool ok;
        bytes memory ret;
        (ok, ret) = address(c).call{value: a}(abi.encodeWithSignature("play()"));
        assert(!ok || c.pot() > 0 || address(c).balance <= balBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint v) public {
        require(address(this).balance >= 2 * v);
        uint start = address(this).balance;
        c.play{value: v}();
        c.play{value: v}();
        assert(c.pot() != 0 || address(this).balance - start >= 2 * v - 2);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function check(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        uint before = c.pot();
        c.play{value: amount}();
        assert(c.pot() == before + amount);
    }

    receive() external payable {}
    fallback() external payable {}
}
